#!/usr/bin/env bash
# Legacy wrapper — F4 was split into F4 (topology) + F5 (conversion).
# This wrapper only compiles the .tex to _archive/ for reference.
# The current F4 and F5 PDFs are generated by snrnaseq/03 and snrnaseq/07.

set -u

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
TEX="$SCRIPT_DIR/F4_snrnaseq_panels.tex"
ARCHIVE_DIR="$REPO_ROOT/_archive/components"

if [[ ! -f "$TEX" ]]; then
  echo "[ERROR] Source not found: $TEX" >&2
  exit 1
fi

mkdir -p "$ARCHIVE_DIR"
cd "$SCRIPT_DIR"
pdflatex -interaction=nonstopmode F4_snrnaseq_panels.tex >/tmp/F4_compile.log 2>&1 || true
rm -f F4_snrnaseq_panels.aux F4_snrnaseq_panels.log F4_snrnaseq_panels.out

if [[ -f "$SCRIPT_DIR/F4_snrnaseq_panels.pdf" ]] && [[ -s "$SCRIPT_DIR/F4_snrnaseq_panels.pdf" ]]; then
  mv "$SCRIPT_DIR/F4_snrnaseq_panels.pdf" "$ARCHIVE_DIR/"
  echo "[OK] F4_snrnaseq_panels.pdf -> _archive/components/ (legacy)"
  exit 0
else
  echo "[ERROR] PDF not produced. See /tmp/F4_compile.log" >&2
  tail -15 /tmp/F4_compile.log >&2
  exit 1
fi
